// Modern build only: which overlays are loaded, and calls to addresses that several overlays share (see
// docs/modern.md, "Shared overlay addresses").
//
// The original's main code holds fixed addresses inside overlays (action tables, callbacks); the same address is a
// different function depending on the overlay loaded there. The modern build places overlays elsewhere, so each such
// reference goes to a thunk (generated by tools/modern_shared.py, through ld --wrap) that asks
// Modern_SharedResolve for the candidate whose overlay is loaded.

#include "types.h"

#define MODERN_MAX_OVERLAYS 160

static u8 sOverlayLoaded[MODERN_MAX_OVERLAYS];
static u32 sOverlayStart[MODERN_MAX_OVERLAYS];
static u32 sOverlayEnd[MODERN_MAX_OVERLAYS];

// FS_StartOverlay: an overlay was loaded over [start, end); the overlays it overlaps are gone
void Modern_OverlayStarted(u32 id, u32 start, u32 end) {
    u32 i;
    for (i = 0; i < MODERN_MAX_OVERLAYS; i++) {
        if (sOverlayLoaded[i] && sOverlayStart[i] < end && start < sOverlayEnd[i]) {
            sOverlayLoaded[i] = 0;
        }
    }
    if (id < MODERN_MAX_OVERLAYS) {
        sOverlayLoaded[id] = 1;
        sOverlayStart[id] = start;
        sOverlayEnd[id] = end;
    }
}

// FS_EndOverlay
void Modern_OverlayEnded(u32 id) {
    if (id < MODERN_MAX_OVERLAYS) {
        sOverlayLoaded[id] = 0;
    }
}

BOOL Modern_IsOverlayLoaded(u32 id) {
    return id < MODERN_MAX_OVERLAYS && sOverlayLoaded[id];
}

// entry: count, then (overlay id, address) pairs, the name the source uses first. An address of 0 is a candidate
// the modern build doesn't define (a weak reference).
// entry: count, then (overlay, address) pairs; pointer-sized words (32 bits on the DS and i386, 64 on x86-64)
void *Modern_SharedResolve(const unsigned long *entry) {
    unsigned long n = entry[0];
    unsigned long i;
    for (i = 0; i < n; i++) {
        unsigned long id = entry[1 + 2 * i];
        unsigned long addr = entry[2 + 2 * i];
        if (addr != 0 && Modern_IsOverlayLoaded(id)) {
            return (void *)addr;
        }
    }
    return (void *)entry[2];
}
